const std = @import("std");

pub fn main() !void {
    const width: i32 = 7;
    const height: i32 = 12;

    const area = width * height;
    const perimeter = 2 * (width + height);

    std.debug.print("Area: {}\n", .{area});
    std.debug.print("Perimeter: {}\n", .{perimeter});
}

